import{_ as l,H as t,f as e,i as a}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"20 | Agent：24小时不睡觉的超级员工","description":"","frontmatter":{},"headers":[{"level":2,"title":"核心进化：ReAct 模式（思考与行动）","slug":"核心进化-react-模式-思考与行动","link":"#核心进化-react-模式-思考与行动","children":[{"level":3,"title":"场景示例：深夜突发利空","slug":"场景示例-深夜突发利空","link":"#场景示例-深夜突发利空","children":[]}]},{"level":2,"title":"给 AI 装上手：Function Calling（工具调用）","slug":"给-ai-装上手-function-calling-工具调用","link":"#给-ai-装上手-function-calling-工具调用","children":[]},{"level":2,"title":"从单兵作战到军团作战：Multi-Agent（多智能体）","slug":"从单兵作战到军团作战-multi-agent-多智能体","link":"#从单兵作战到军团作战-multi-agent-多智能体","children":[]},{"level":2,"title":"最大的风险：AI 的肥手指与死循环","slug":"最大的风险-ai-的肥手指与死循环","link":"#最大的风险-ai-的肥手指与死循环","children":[]},{"level":2,"title":"解决方案：构建双重安全锁","slug":"解决方案-构建双重安全锁","link":"#解决方案-构建双重安全锁","children":[]},{"level":2,"title":"未来展望：从量化策略到管理策略","slug":"未来展望-从量化策略到管理策略","link":"#未来展望-从量化策略到管理策略","children":[]},{"level":2,"title":"AI 量化策略建议","slug":"ai-量化策略建议","link":"#ai-量化策略建议","children":[]},{"level":2,"title":"本讲金句弹幕","slug":"本讲金句弹幕","link":"#本讲金句弹幕","children":[]},{"level":2,"title":"课后思考题","slug":"课后思考题","link":"#课后思考题","children":[]},{"level":2,"title":"下节预告","slug":"下节预告","link":"#下节预告","children":[]}],"relativePath":"人人都用得上的AI量化思维课/20｜Agent：24小时不睡觉的超级员工.md","filePath":"人人都用得上的AI量化思维课/20｜Agent：24小时不睡觉的超级员工.md","lastUpdated":1795541548000}'),p={name:"人人都用得上的AI量化思维课/20｜Agent：24小时不睡觉的超级员工.md"};function n(s,i,o,r,h,g){return t(),e("div",null,[...i[0]||(i[0]=[a(`<h1 id="_20-agent-24小时不睡觉的超级员工" tabindex="-1">20 | Agent：24小时不睡觉的超级员工 <a class="header-anchor" href="#_20-agent-24小时不睡觉的超级员工" aria-label="Permalink to &quot;20 | Agent：24小时不睡觉的超级员工&quot;">​</a></h1><p>你好，我是陈旸。</p><p>在过去的 3 年里，生成式 AI 经历了 3 个阶段：</p><ol><li><p>Chatbot（聊天机器人）阶段：你问它“什么是均线”，它回答你。这是知识检索。</p></li><li><p>Copilot（副驾驶）阶段：你写代码卡住了，它帮你补全。这是辅助工具。</p></li><li><p>Agent（智能体）阶段：它的目标是全自动驾驶，基于你的需求，自主进行规划，利用各种工具和知识库经验，分成多个步骤一步一步来完成。</p></li></ol><p>简单来说：Agent = LLM（大模型大脑）+ Memory（记忆）+ Planning（规划）+ Tools（工具使用）。</p><p>通俗点说：DeepSeek 就像一个被关在小黑屋里的博士，他知道所有的知识，但他没有任何工具，连网都上不了（早期版本）。Agent 就是把这个博士放出来，给他一台联网的电脑，给他QMT 的交易权限，给他无限的硬盘空间。你只跟他说一句话：“帮我编写双均线策略，并针对贵州茅台进行 2024-2025 年的策略回测。” 他就会自己去拆解任务、自己查资料、自己写策略、自己下单。这就是具身智能在数字世界的形态。</p><h2 id="核心进化-react-模式-思考与行动" tabindex="-1">核心进化：ReAct 模式（思考与行动） <a class="header-anchor" href="#核心进化-react-模式-思考与行动" aria-label="Permalink to &quot;核心进化：ReAct 模式（思考与行动）&quot;">​</a></h2><p>为什么 Agent 能自己干活？ 因为它学会了一种人类独有的思维方式——ReAct（Reasoning +Acting，推理 + 行动）。在传统量化脚本（Python）里，代码是一行行死板执行的：如果是价格突破 20 日均线 =&gt; 买入 =&gt; 结束。而在 Agent 的世界里，它有一个内心独白的循环。</p><h3 id="场景示例-深夜突发利空" tabindex="-1">场景示例：深夜突发利空 <a class="header-anchor" href="#场景示例-深夜突发利空" aria-label="Permalink to &quot;场景示例：深夜突发利空&quot;">​</a></h3><p>凌晨 3 点，大洋彼岸传来消息，美联储意外加息。</p><ul><li><p>Agent 的内心独白（Loop 1）：</p></li><li><p>感知（Observation）：监控到财联社推送美联储加息 50 个基点。</p></li><li><p>思考（Thought）：这比预期的 25 个基点要高，是重大利空。我的持仓里有高估值的科技股，风险很大。</p></li><li><p>行动（Action）：调用 check_portfolio() 函数，查看当前持仓。</p></li><li><p>Agent 的内心独白（Loop 2）：</p></li><li><p>感知：持仓显示持有英伟达 1000 股。</p></li><li><p>思考：科技股对利率敏感，必须对冲风险。但我现在不能卖（美股收盘了 /A 股还没开盘）。我需要去期货市场做空对冲。</p></li><li><p>行动：调用 trade_futures() 函数，做空对应名义价值的纳指期货。</p></li><li><p>Agent 的内心独白（Loop 3）：</p></li><li><p>感知：下单成功。</p></li><li><p>思考：风险已对冲。记录日志，并发微信通知主人。</p></li><li><p>行动：发送微信消息。</p></li></ul><p>你看，这不再是一个死的脚本，这是一个会根据环境变化，动态调整策略的活人。它不需要你预设每一种情况（if-else），它利用大模型的常识（加息 = 利空科技）来进行逻辑推理，并自主调用工具解决问题。</p><h2 id="给-ai-装上手-function-calling-工具调用" tabindex="-1">给 AI 装上手：Function Calling（工具调用） <a class="header-anchor" href="#给-ai-装上手-function-calling-工具调用" aria-label="Permalink to &quot;给 AI 装上手：Function Calling（工具调用）&quot;">​</a></h2><p>Agent 之所以能干活，核心在于 Function Calling（工具调用）技术。这是连接自然语言和量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>化代码的桥梁。以前，你想让程序下单，你得写 order_target_value(&#39;600519.SH&#39;,</span></span>
<span class="line"><span>10000)。现在，你只需要把这个函数注册给 Agent。然后你对 Agent 说：“帮我买一万块钱茅</span></span></code></pre></div><p>台。”Agent 的大脑（LLM）会解析这句话：</p><ol><li><p>意图识别：用户想买股票。</p></li><li><p>参数提取：</p></li></ol><ul><li><p>股票代码：茅台 -&gt; 600519.SH（它自己会去查代码表）。1.</p></li><li><p>金额：10000。2.</p></li></ul><ol start="3"><li>JSON 输出：它不会直接下单，而是输出一个标准的 JSON 格式给交易系统。</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order_target_value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;600519.SH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span></span></code></pre></div><p>QMT 交易系统接收到这个 JSON，执行下单。</p><p>量化视角的颠覆：这意味着，你不需要再手写那些繁琐的 API 了。你可以定义几十个工具：查研报、算 RSI、画 K 线、下单、撤单…… 然后让 Agent 自己去组合使用这些工具。它就像一个拿着瑞士军刀的特种兵，遇到什么困难，就拔出哪把刀。</p><h2 id="从单兵作战到军团作战-multi-agent-多智能体" tabindex="-1">从单兵作战到军团作战：Multi-Agent（多智能体） <a class="header-anchor" href="#从单兵作战到军团作战-multi-agent-多智能体" aria-label="Permalink to &quot;从单兵作战到军团作战：Multi-Agent（多智能体）&quot;">​</a></h2><p>一个 Agent 能力再强，也容易产生幻觉，或者顾此失彼。量化交易是一个复杂的系统工程，需要分工协作。在 AI 量化思维中，可以采用先进的多智能体架构（Multi-Agent System）。我们可以用 LangGraph 这样的框架，组建一个 AI 投研部。</p><p>让我们来看看你的 AI 员工们：</p><ol><li>角色 A：信息搜集员（Charles）</li></ol><ul><li><p>任务：24 小时爬取新闻、公告、推特。1.</p></li><li><p>2.人设：八卦、敏感、速度快。</p></li><li><p>输出：每天早上 8 点，扔出一份今日重点情报摘要。3.</p></li></ul><ol start="2"><li>角色 B：数据分析师（Zoe）</li></ol><ul><li><p>任务：收到 Charles 的情报后，去拉取相关的 K 线、财报数据，跑一遍多因子模型。1.</p></li><li><p>2.人设：严谨、数学好、甚至有点死板。</p></li><li><p>输出：“基于情报，该股票技术面 RSI 金叉，估值处于低位，胜率预测 65%。”3.</p></li></ul><ol start="3"><li>角色 C：风控官（Kriss）</li></ol><ul><li><p>任务：审核 Zoe 的建议。1.</p></li><li><p>2.人设：悲观、胆小，甚至有点讨厌。他只盯着回撤和仓位。</p></li><li><p>输出：“虽然胜率 65%，但当前总仓位已达 80%，且该板块波动率过大。否决买入建3.议，或建议只买 1% 仓位。”</p></li></ul><ol start="4"><li>角色 D：交易员（Ethan）</li></ol><ul><li><p>任务：执行 Kris 批准的指令。1.</p></li><li><p>2.人设：冷酷、算法专家。</p></li><li><p>输出：使用 TWAP 算法拆单，悄悄完成建仓。3.</p></li></ul><p>这就是左右互搏。让 AI 审核 AI，让 AI 制约 AI。通过这种角色扮演和 SOP（标准作业程序），我们可以大大降低 AI 产生幻觉的风险，提高系统的稳健性。</p><h2 id="最大的风险-ai-的肥手指与死循环" tabindex="-1">最大的风险：AI 的肥手指与死循环 <a class="header-anchor" href="#最大的风险-ai-的肥手指与死循环" aria-label="Permalink to &quot;最大的风险：AI 的肥手指与死循环&quot;">​</a></h2><p>Agent 听起来很梦幻，但在实盘中，它也可能变成噩梦。</p><p>风险 1：死循环</p><p>Agent 有时候会陷入一种执念。比如它想买入某只股票，但是挂单没成交（价格变了）。它的ReAct 循环可能会这样：“没成交 -&gt; 撤单 -&gt; 提价 1 分钱再买 -&gt; 还没成交 -&gt; 撤单 -&gt; 再提价……” 如果在高频交易中，这个循环没写好退出机制，它可能在 1 分钟内把你一年的手续费都刷光，甚至把股价拉涨停（类似光大乌龙指）。</p><p>风险 2：幻觉执行（概率性灾难）</p><p>这是 AI 特有的风险。万一大脑（LLM）抽风了呢？ LLM 本质上是概率模型，不是逻辑机器。</p><ul><li><p>它可能把“卖出 100 股”幻视成了“卖出 100 万股”。</p></li><li><p>它可能把“600519（茅台）”识别成了“600518（康美，已退市）”。</p></li><li><p>它甚至可能编造一个不存在的股票代码，导致程序报错崩溃。</p></li></ul><h2 id="解决方案-构建双重安全锁" tabindex="-1">解决方案：构建双重安全锁 <a class="header-anchor" href="#解决方案-构建双重安全锁" aria-label="Permalink to &quot;解决方案：构建双重安全锁&quot;">​</a></h2><p>为了防止 AI 发疯，我们必须给它戴上镣铐。</p><p>第一道锁：确定性校验层</p><p>这是最重要的一层防护。请记住：LLM 输出的是 JSON 指令，中间必须隔着一层硬代码（Hard Code）逻辑检查。这层检查代码不能是 AI 写的，必须是你写死的规则，且没有任何商量余地。</p><ul><li><p>金额熔断：if order_amount &gt; 50000: REJECT （单笔超过 5 万，直接驳回，不管 AI 觉得机会多好）。</p></li><li><p>价格偏离：if order_price &gt; current_price * 1.02: REJECT （买入价偏离现价 2%，直接驳回，防止滑点）。</p></li><li><p>白名单检查：if symbol not in stock_pool: REJECT （不在股票池里的，不许买）。</p></li></ul><p>这层硬代码就像物理世界的保险丝。无论 Agent 多么聪明或多么疯狂，只要触碰了红线，电流直接切断。我们后面会详细讲解这层代码该怎么写。</p><p>第二道锁：HITL（Human-in-the-Loop，人类在环）</p><p>通过了第一道硬代码检查后，对于大资金操作，还不能直接发给交易所。</p><ul><li><p>Agent 生成一个通过了初步校验的订单列表。</p></li><li><p>它会发一条消息到你的手机：“老板，我建议买入这 3 只股票，理由如下……硬代码风控已通过，请批准 / 拒绝。”</p></li><li><p>你按一下批准，它才真正发送指令给 QMT。</p></li></ul><p>这就是半人马模式。AI 负责 99% 的计算和生成，硬代码负责过滤掉荒谬的错误，人类负责这最后 1% 的责任承担。</p><h2 id="未来展望-从量化策略到管理策略" tabindex="-1">未来展望：从量化策略到管理策略 <a class="header-anchor" href="#未来展望-从量化策略到管理策略" aria-label="Permalink to &quot;未来展望：从量化策略到管理策略&quot;">​</a></h2><p>Agent 技术的出现，正在从根本上改变量化交易的定义。以前，量化交易员的工作是写策略（编写数学公式）。未来，量化交易员的工作是管理员工（设计 Agent 的提示词 Prompt 和工作流）。</p><p>你不需要去研究怎么算 MACD（Agent 自带工具包），你需要研究的是：</p><ul><li><p>怎么设计一个更聪明的风控 Agent，让它能拦住激进的交易 Agent？</p></li><li><p>怎么设计情报 Agent 的 Prompt，让它不会错过重要的宏观线索？</p></li></ul><p>你的核心竞争力，从代码能力转移到了系统架构能力和对金融本质的理解。这就好比西蒙斯（大奖章基金创始人）不再自己算题，而是专注于雇佣最聪明的科学家，并给他们创造最好的环境。在 AI 时代，你就是那个西蒙斯，而 Agent 就是你雇佣的那群顶级科学家。</p><h2 id="ai-量化策略建议" tabindex="-1">AI 量化策略建议 <a class="header-anchor" href="#ai-量化策略建议" aria-label="Permalink to &quot;AI 量化策略建议&quot;">​</a></h2><p>Agent 时代已经到来，虽然还在早期，但进化速度极快。我有三条建议，助你拿到这张通往未来的船票：</p><ol><li>学习 LangChain 和 LangGraph</li></ol><p>这是开发 Agent 的主流框架。我会在《AI 量化交易训练营》将教你使用 LangGraph 打造你的多智能体员工，它能帮你把 Prompt、记忆、工具串联起来，像搭积木一样。</p><ol start="2"><li>建立工具库思维</li></ol><p>不要总想着写一个大而全的策略，要把功能拆碎。写一个计算 RSI 的小函数，写一个查询新闻的小函数。这些小函数就是你喂给 Agent 的技能书。你的技能书越丰富，你的 Agent 就越强大。</p><ol start="3"><li>始终保持人的一票否决权</li></ol><p>不管 AI 看起来多聪明，钱是你的。在很长一段时间内，不要把账户密码完全交给它。把Agent 当成最得力的参谋长，而不是独裁者。</p><h2 id="本讲金句弹幕" tabindex="-1">本讲金句弹幕 <a class="header-anchor" href="#本讲金句弹幕" aria-label="Permalink to &quot;本讲金句弹幕&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/20/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/20/1.png" alt=""></a></p><h2 id="课后思考题" tabindex="-1">课后思考题 <a class="header-anchor" href="#课后思考题" aria-label="Permalink to &quot;课后思考题&quot;">​</a></h2><p>如果让你设计一个简单的双 Agent 系统：</p><ul><li><p>Agent A 负责看多（永远寻找买入理由）。</p></li><li><p>Agent B 负责看空（永远寻找卖出理由）。它们两个针对同一只股票进行辩论。你会给它们设计什么样的 Prompt（人设）？ 你作为裁判（Human），会根据什么标准来判定谁赢了？</p></li></ul><h2 id="下节预告" tabindex="-1">下节预告 <a class="header-anchor" href="#下节预告" aria-label="Permalink to &quot;下节预告&quot;">​</a></h2><p>有了 AI 员工（Agent），我们需要喂给他什么数据？不光是 K 线，在下一讲我们将进入另类数据的世界，看看还有哪些另类数据，可以让你领先市场，赚取额外的收益。</p>`,71)])])}const c=l(p,[["render",n]]);export{A as __pageData,c as default};
